ddl:
CREATE TABLE Parking (
    Parking_Space_ID INTEGER PRIMARY KEY,
    Parking_Space_Status VARCHAR(255)
);

CREATE TABLE Entrance (
    Entrance_Location VARCHAR(255),
    Entrance_Number INTEGER PRIMARY KEY
);

CREATE TABLE Exit (
    Exit_Location VARCHAR(255),
    Exit_Number INTEGER PRIMARY KEY
);

CREATE TABLE Vehicle (
    License_Plate_Number INTEGER,
    Vehicle_ID INTEGER PRIMARY KEY,
    Vehicle_Model VARCHAR(255)
);

CREATE TABLE Parking_Record (
    Entrance_Number INTEGER NOT NULL,
    Entry_Time DATETIME,
    Exit_Number INTEGER NOT NULL,
    Exit_Time DATETIME,
    Parking_Duration FLOAT,
    Parking_Fee FLOAT,
    Parking_Space_ID INTEGER NOT NULL,
    Vehicle_ID INTEGER NOT NULL,
    PRIMARY KEY (Parking_Space_ID, Vehicle_ID),
    FOREIGN KEY (Entrance_Number) REFERENCES Entrance(Entrance_Number),
    FOREIGN KEY (Exit_Number) REFERENCES Exit(Exit_Number),
    FOREIGN KEY (Parking_Space_ID) REFERENCES Parking(Parking_Space_ID),
    FOREIGN KEY (Vehicle_ID) REFERENCES Vehicle(Vehicle_ID)
);
